Map<Integer, Integer> lastSeen = new HashMap<>();
int best = Integer.MAX_VALUE;
for (int i = 0; i < A.length; i++) {
    if (lastSeen.containsKey(A[i])) {
        best = Math.min(best, i - lastSeen.get(A[i]));
    }
    lastSeen.put(A[i], i);   // always overwrite: the nearest one is the useful one
}
return best == Integer.MAX_VALUE ? -1 : best;

int[] need = new int[256];
for (char c : B.toCharArray()) {
    need[c]++;
}
int missing = B.length();
int left = 0, bestLen = Integer.MAX_VALUE, bestStart = -1;
for (int right = 0; right < A.length(); right++) {
    if (need[A.charAt(right)] > 0) {
        missing--;              // only required chars reduce the deficit
    }
    need[A.charAt(right)]--;
    while (missing == 0) {
        if (right - left + 1 < bestLen) {
            bestLen = right - left + 1;
            bestStart = left;
        }
        need[A.charAt(left)]++;
        if (need[A.charAt(left)] > 0) {
            missing++;
        }
        left++;
    }
}

int profit = 0;
for (int i = 1; i < A.length; i++) {
    if (A[i] > A[i - 1]) {
        profit += A[i] - A[i - 1];
    }
}
return profit;

// the A-th palindrome of this family = binary of (A + 1) with its
// leading bit dropped, mirrored around the centre
StringBuilder half = new StringBuilder(Integer.toBinaryString(A + 1));
half.deleteCharAt(0);
StringBuilder full = new StringBuilder(half);
full.append(new StringBuilder(half).reverse());
return full.toString();
